import sys

sys.setrecursionlimit(2000000)

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
    except StopIteration:
        return

    matrix = []
    for _ in range(n):
        row = []
        for _ in range(n):
            row.append(int(next(iterator)))
        matrix.append(row)

    MOD = 10**9 + 7
    dp = [[-1] * n for _ in range(n)]

    def count_paths(r, c):
        if dp[r][c] != -1:
            return dp[r][c]

        current_val = matrix[r][c]
        total = 1  # Path consisting of just this cell

        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        for dr, dc in directions:
            nr, nc = r + dr, c + dc

            if 0 <= nr < n and 0 <= nc < n:
                if matrix[nr][nc] < current_val:
                    total = (total + count_paths(nr, nc)) % MOD

        dp[r][c] = total
        return total

    result = 0
    for i in range(n):
        for j in range(n):
            result = (result + count_paths(i, j)) % MOD

    print(result)

if __name__ == "__main__":
    main()
